-- ── hand-written: a draft is the app's, everything after it the database's ──────────────────────
-- Not SECURITY DEFINER: these run as whoever writes the row, so current_user says who that is. The
-- app writes as app_runtime and is checked; the database's own functions below run as their owner
-- and stamp who and when themselves.
CREATE FUNCTION app.check_payroll_run_row() RETURNS trigger
  LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF current_user <> 'app_runtime' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'a payroll run is never removed; cancel it instead' USING ERRCODE = 'SE351';
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'a payroll run starts as a draft' USING ERRCODE = 'SE351';
    END IF;
    NEW.created_at := now();
    NEW.created_by := app.current_user_id();
    NEW.worked_out_at := clock_timestamp();
  ELSE
    -- The app works a draft or a reviewed run out again, which makes it a draft; nothing else.
    IF OLD.status NOT IN ('draft', 'reviewed') OR NEW.status <> 'draft' OR NEW.month <> OLD.month THEN
      RAISE EXCEPTION 'only a draft or reviewed run is worked out again, and it is a draft once more' USING ERRCODE = 'SE351';
    END IF;
    NEW.reviewed_at := NULL;
    NEW.reviewed_by := NULL;
    NEW.worked_out_at := clock_timestamp();
  END IF;
  NEW.updated_at := clock_timestamp();
  NEW.updated_by := app.current_user_id();
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_payroll_run_row() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER payroll_runs_check BEFORE INSERT OR UPDATE OR DELETE ON public.payroll_runs FOR EACH ROW EXECUTE FUNCTION app.check_payroll_run_row();
--> statement-breakpoint
ALTER TABLE public.payroll_runs ENABLE ALWAYS TRIGGER payroll_runs_check;
--> statement-breakpoint
-- A payslip and its lines are written and thrown away only while their run is a draft.
CREATE FUNCTION app.check_payslip_row() RETURNS trigger
  LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_row record;
  v_run uuid;
BEGIN
  IF current_user <> 'app_runtime' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    v_row := OLD;
  ELSE
    v_row := NEW;
  END IF;
  IF v_row.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF TG_TABLE_NAME = 'payslips' THEN
    v_run := v_row.run_id;
  ELSE
    SELECT p.run_id INTO v_run FROM public.payslips p WHERE p.tenant_id = v_row.tenant_id AND p.id = v_row.payslip_id;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.payroll_runs r WHERE r.tenant_id = v_row.tenant_id AND r.id = v_run AND r.status = 'draft') THEN
    RAISE EXCEPTION 'a payslip is written only while its run is a draft' USING ERRCODE = 'SE351';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  IF TG_TABLE_NAME = 'payslips' THEN
    NEW.created_at := now();
    NEW.created_by := app.current_user_id();
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_payslip_row() FROM PUBLIC;
--> statement-breakpoint
