--> statement-breakpoint
ALTER TABLE public.payslips ENABLE ALWAYS TRIGGER payslips_check;
--> statement-breakpoint
CREATE TRIGGER payslip_lines_check BEFORE INSERT OR DELETE ON public.payslip_lines FOR EACH ROW EXECUTE FUNCTION app.check_payslip_row();
