-- ── hand-written: the commission a run carries ──────────────────────────────────────────────────
-- What a person's commission stands at for paying: each approved accrual with what its customers'
-- money has released and is unpaid, and each accrual on which they were paid more than is now
-- released (owed back). Not for the app to call: the two functions below are its way in.
CREATE FUNCTION app.commission_basis_of(p_tenant uuid, p_user uuid) RETURNS jsonb
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT jsonb_build_object(
      'due', coalesce((SELECT jsonb_object_agg(a.id::text, trim_scale(a.released - a.paid)::text ORDER BY a.id) FROM public.commission_accruals a
        WHERE a.tenant_id = p_tenant AND a.user_id = p_user AND a.approved_at IS NOT NULL AND a.released > a.paid), '{}'::jsonb),
      'owed', coalesce((SELECT jsonb_object_agg(a.id::text, trim_scale(a.paid - a.released)::text ORDER BY a.id) FROM public.commission_accruals a
        WHERE a.tenant_id = p_tenant AND a.user_id = p_user AND a.paid > a.released), '{}'::jsonb))
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.commission_basis_of(uuid, uuid) FROM PUBLIC;
--> statement-breakpoint
-- The app works a payslip out from this, and approval asks it again: a run is never approved on
-- commission that has changed since (the step's acceptance). The payroll administrator, who does
-- not read commission, gets these figures for the people on the payroll, and for nobody else.
CREATE FUNCTION app.payroll_commission_basis(p_user uuid) RETURNS jsonb
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
BEGIN
  IF v_tenant IS NULL OR app.tenant_role() IS NULL OR app.tenant_role() NOT IN ('owner', 'payroll_administrator') OR app.tenant_branch_ids() IS NOT NULL THEN
    RAISE EXCEPTION 'this role does not work out payroll' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.employees e WHERE e.tenant_id = v_tenant AND e.user_id = p_user) THEN
    RAISE EXCEPTION 'nobody on the payroll signs in as that person' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN app.commission_basis_of(v_tenant, p_user);
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.payroll_commission_basis(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.payroll_commission_basis(uuid) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: reviewing, approving, paying and cancelling ───────────────────────────────────
-- Not for the app to call. A run held, for one of the acts below.
CREATE FUNCTION app.hold_payroll_run(p_run uuid) RETURNS public.payroll_runs
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_run public.payroll_runs%ROWTYPE;
BEGIN
  IF app.tenant_id() IS NULL OR app.current_user_id() IS NULL OR app.tenant_branch_ids() IS NOT NULL THEN
    RAISE EXCEPTION 'payroll is run by someone who works in every branch' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'payroll is run in read committed transactions' USING ERRCODE = 'SE352';
  END IF;
  SELECT r.* INTO v_run FROM public.payroll_runs r WHERE r.tenant_id = app.tenant_id() AND r.id = p_run FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such payroll run in this company' USING ERRCODE = 'SE353';
  END IF;
  RETURN v_run;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.hold_payroll_run(uuid) FROM PUBLIC;
--> statement-breakpoint
-- A draft is reviewed by the owner or the payroll administrator: its payslips are what they say.
CREATE FUNCTION app.review_payroll_run(p_run uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_run public.payroll_runs%ROWTYPE := app.hold_payroll_run(p_run);
BEGIN
  IF app.tenant_role() NOT IN ('owner', 'payroll_administrator') THEN
    RAISE EXCEPTION 'a run is reviewed by the owner or the payroll administrator' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_run.status <> 'draft' THEN
    RAISE EXCEPTION 'only a draft is reviewed' USING ERRCODE = 'SE354';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.payslips p WHERE p.tenant_id = v_run.tenant_id AND p.run_id = v_run.id) THEN
    RAISE EXCEPTION 'the run has no payslips' USING ERRCODE = 'SE354';
  END IF;
  UPDATE public.payroll_runs r SET status = 'reviewed', reviewed_at = now(), reviewed_by = app.current_user_id(), updated_at = now(), updated_by = app.current_user_id()
    WHERE r.tenant_id = v_run.tenant_id AND r.id = v_run.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
    VALUES (v_run.tenant_id, app.current_user_id(), app.tenant_role(), 'payroll_run.review', 'payroll_run', v_run.id,
      jsonb_build_object('status', 'draft'), jsonb_build_object('status', 'reviewed', 'month', v_run.month, 'net', v_run.net::text));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.review_payroll_run(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.review_payroll_run(uuid) TO app_runtime;
--> statement-breakpoint

-- A reviewed run is approved by the owner or an accountant: it goes into the books, dated the
-- month's last day (or the day it is approved, if that comes first), and the commission it carries
-- is settled, never expensed again:
--   debit   Salaries and wages                      the pay, less fixed deductions
--   debit   Employer EOBI and social security       the employer's EOBI and social security
--   debit   Commission payable                      the commission carried (expensed when earned)
--   credit  Salaries payable                        what the people take home
--   credit  Income tax withheld payable             the tax deducted from pay (s.149)
--   credit  EOBI and social security payable        the employees' EOBI and the employer's share
CREATE FUNCTION app.approve_payroll_run(p_run uuid) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_run public.payroll_runs%ROWTYPE := app.hold_payroll_run(p_run);
  v_tenant uuid := v_run.tenant_id;
  v_me uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_today date := (now() AT TIME ZONE 'Asia/Karachi')::date;
  v_date date;
  v_slip record;
  v_row record;
  v_basis jsonb;
  v_gross numeric;
  v_owed numeric;
  v_recovered numeric;
  v_take numeric;
  v_sum record;
  v_salaries numeric;
  v_employer numeric;
  v_statutory numeric;
  v_number text;
  v_journal uuid;
  v_no integer := 0;
BEGIN
  IF v_role NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'a run is approved by the owner or an accountant' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_run.status <> 'reviewed' THEN
    RAISE EXCEPTION 'only a reviewed run is approved' USING ERRCODE = 'SE354';
  END IF;
  IF v_run.month > v_today THEN
    RAISE EXCEPTION 'a month is approved once it has begun' USING ERRCODE = 'SE355';
  END IF;
  v_date := least((v_run.month + interval '1 month' - interval '1 day')::date, v_today);
  PERFORM app.require_open_period(v_tenant, v_date);
  -- The payslips add up to the run, each to itself.
  SELECT coalesce(sum(p.earnings), 0) AS earnings, coalesce(sum(p.commission), 0) AS commission, coalesce(sum(p.tax), 0) AS tax, coalesce(sum(p.eobi_employee), 0) AS eobi,
         coalesce(sum(p.deductions), 0) AS deductions, coalesce(sum(p.net), 0) AS net, coalesce(sum(p.employer_eobi), 0) AS employer_eobi,
         coalesce(sum(p.employer_social_security), 0) AS employer_ss, count(*) AS slips
    INTO v_sum FROM public.payslips p WHERE p.tenant_id = v_tenant AND p.run_id = v_run.id;
  IF v_sum.slips = 0 OR v_sum.earnings <> v_run.earnings OR v_sum.commission <> v_run.commission OR v_sum.tax <> v_run.tax OR v_sum.eobi <> v_run.eobi_employee
     OR v_sum.deductions <> v_run.deductions OR v_sum.net <> v_run.net OR v_sum.employer_eobi <> v_run.employer_eobi OR v_sum.employer_ss <> v_run.employer_social_security THEN
    RAISE EXCEPTION 'the payslips do not add up to the run; work it out again' USING ERRCODE = 'SE356';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.payslips p
    LEFT JOIN LATERAL (
      SELECT coalesce(sum(l.amount) FILTER (WHERE l.kind = 'earning'), 0) AS earning, coalesce(sum(l.amount) FILTER (WHERE l.kind = 'deduction'), 0) AS deduction,
             coalesce(sum(l.amount) FILTER (WHERE l.kind = 'employer'), 0) AS employer
      FROM public.payslip_lines l WHERE l.tenant_id = p.tenant_id AND l.payslip_id = p.id
    ) s ON true
    WHERE p.tenant_id = v_tenant AND p.run_id = v_run.id
      AND (s.earning <> p.earnings + p.commission OR s.deduction <> p.tax + p.eobi_employee + p.deductions OR s.employer <> p.employer_eobi + p.employer_social_security)
  ) THEN
    RAISE EXCEPTION 'a payslip''s lines do not add up to it; work the run out again' USING ERRCODE = 'SE356';
  END IF;
  -- The tax deducted so far this tax year (July to June) is what each payslip was worked out
  -- with: a month approved since, or out of order, would leave this one's tax wrong.
  IF EXISTS (
    SELECT 1 FROM public.payslips p
    LEFT JOIN LATERAL (
      SELECT coalesce(sum(q.taxable), 0) AS taxable, coalesce(sum(q.tax), 0) AS tax
      FROM public.payslips q JOIN public.payroll_runs r ON r.tenant_id = q.tenant_id AND r.id = q.run_id
      WHERE q.tenant_id = p.tenant_id AND q.employee_id = p.employee_id AND r.status IN ('approved', 'paid')
        AND r.month >= make_date(extract(year FROM v_run.month - interval '6 months')::int, 7, 1) AND r.month < v_run.month
    ) b ON true
    WHERE p.tenant_id = v_tenant AND p.run_id = v_run.id AND (b.taxable <> p.taxable_before OR b.tax <> p.tax_before)
  ) THEN
    RAISE EXCEPTION 'a month of this tax year has been approved since this run was worked out; work it out again' USING ERRCODE = 'SE356';
  END IF;

  -- Commission: each person's, as it stands now, must be what the run was worked out with.
  FOR v_slip IN
    SELECT p.id, p.user_id, p.commission, p.commission_recovered, p.commission_basis, e.name
    FROM public.payslips p JOIN public.employees e ON e.tenant_id = p.tenant_id AND e.id = p.employee_id
    WHERE p.tenant_id = v_tenant AND p.run_id = v_run.id AND p.user_id IS NOT NULL
    ORDER BY p.user_id
  LOOP
    -- As a commission payment does (drizzle/0027_commission_ledger.sql): the person's membership
    -- is held, so nothing is accrued for them and no payment made meanwhile, and something being
    -- recorded on one of their invoices right now is let finish first, never waited for.
    PERFORM 1 FROM public.memberships m WHERE m.tenant_id = v_tenant AND m.user_id = v_slip.user_id FOR NO KEY UPDATE;
    BEGIN
      PERFORM 1 FROM public.commission_accruals a WHERE a.tenant_id = v_tenant AND a.user_id = v_slip.user_id ORDER BY a.id FOR UPDATE NOWAIT;
    EXCEPTION WHEN lock_not_available THEN
      RAISE EXCEPTION 'something is being recorded on one of %''s invoices right now; try again', v_slip.name USING ERRCODE = 'SE357';
    END;
    v_basis := app.commission_basis_of(v_tenant, v_slip.user_id);
    IF v_basis IS DISTINCT FROM v_slip.commission_basis THEN
      RAISE EXCEPTION 'the commission of % has changed since this run was worked out; work it out again', v_slip.name USING ERRCODE = 'SE350';
    END IF;
    SELECT coalesce(sum(a.released - a.paid), 0) INTO v_gross FROM public.commission_accruals a
      WHERE a.tenant_id = v_tenant AND a.user_id = v_slip.user_id AND a.approved_at IS NOT NULL AND a.released > a.paid;
    SELECT coalesce(sum(a.paid - a.released), 0) INTO v_owed FROM public.commission_accruals a
      WHERE a.tenant_id = v_tenant AND a.user_id = v_slip.user_id AND a.paid > a.released;
    IF v_slip.commission_recovered <> least(v_gross, v_owed) OR v_slip.commission <> v_gross - least(v_gross, v_owed) THEN
      RAISE EXCEPTION 'the commission on %''s payslip is not what is due; work the run out again', v_slip.name USING ERRCODE = 'SE350';
    END IF;
    IF v_gross > 0 AND EXISTS (
      SELECT 1 FROM public.commission_accruals a
      JOIN public.commission_movements m ON m.tenant_id = a.tenant_id AND m.accrual_id = a.id
      WHERE a.tenant_id = v_tenant AND a.user_id = v_slip.user_id AND m.movement_date > v_date
        AND ((a.approved_at IS NOT NULL AND a.released > a.paid) OR a.paid > a.released)
    ) THEN
      RAISE EXCEPTION 'commission is settled on or after the day it was released; approve the run on or after that day' USING ERRCODE = 'SE358';
    END IF;
    -- Settled as Step 38 pays it: what is approved and released is paid; what was owed back is
    -- taken from it, oldest first, as far as it goes. Its journal is the run's.
    FOR v_row IN
      SELECT a.id, a.released - a.paid AS due FROM public.commission_accruals a
      WHERE a.tenant_id = v_tenant AND a.user_id = v_slip.user_id AND a.approved_at IS NOT NULL AND a.released > a.paid
      ORDER BY a.invoice_date, a.id
    LOOP
      INSERT INTO public.commission_movements (tenant_id, accrual_id, type, amount, movement_date, source_type, source_id, created_by)
        VALUES (v_tenant, v_row.id, 'paid', v_row.due, v_date, 'payroll_run', v_run.id, v_me);
      UPDATE public.commission_accruals a SET paid = a.paid + v_row.due, approved_at = NULL, approved_by = NULL WHERE a.tenant_id = v_tenant AND a.id = v_row.id;
    END LOOP;
    v_recovered := 0;
    IF v_gross > 0 THEN
      FOR v_row IN
        SELECT a.id, a.paid - a.released AS owed FROM public.commission_accruals a
        WHERE a.tenant_id = v_tenant AND a.user_id = v_slip.user_id AND a.paid > a.released
        ORDER BY a.invoice_date, a.id
      LOOP
        v_take := least(v_row.owed, v_gross - v_recovered);
        EXIT WHEN v_take <= 0;
        INSERT INTO public.commission_movements (tenant_id, accrual_id, type, amount, movement_date, source_type, source_id, created_by)
          VALUES (v_tenant, v_row.id, 'recovery_recorded', v_take, v_date, 'payroll_run', v_run.id, v_me);
        UPDATE public.commission_accruals a SET paid = a.paid - v_take WHERE a.tenant_id = v_tenant AND a.id = v_row.id;
        v_recovered := v_recovered + v_take;
      END LOOP;
    END IF;
  END LOOP;

  v_salaries := v_sum.earnings - v_sum.deductions;
  v_employer := v_sum.employer_eobi + v_sum.employer_ss;
  v_statutory := v_sum.eobi + v_employer;
  IF v_sum.earnings + v_sum.commission + v_employer <= 0 THEN
    RAISE EXCEPTION 'the run pays nothing' USING ERRCODE = 'SE356';
  END IF;
  v_number := app.next_document_number('PR', v_date);
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, created_by)
    VALUES (v_tenant, v_date, 'payroll_run', v_run.id, v_number, 'Payroll for ' || to_char(v_run.month, 'FMMonth YYYY'), v_me)
    RETURNING id INTO v_journal;
  IF v_salaries <> 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'salaries_expense'), greatest(v_salaries, 0), greatest(-v_salaries, 0), 'Pay, less fixed deductions');
  END IF;
  IF v_employer > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'payroll_statutory_expense'), v_employer, 0, 'Employer''s EOBI and social security');
  END IF;
  IF v_sum.commission > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'commission_payable'), v_sum.commission, 0, 'Commission paid with the salary');
  END IF;
  IF v_sum.net > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'payroll_payable'), 0, v_sum.net, 'What the people take home');
  END IF;
  IF v_sum.tax > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'wht_income_tax'), 0, v_sum.tax, 'Income tax deducted from pay (s.149)');
  END IF;
  IF v_statutory > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'payroll_statutory_payable'), 0, v_statutory, 'EOBI and social security');
  END IF;
  UPDATE public.payroll_runs r SET status = 'approved', number = v_number, journal_id = v_journal, journal_date = v_date, approved_at = now(), approved_by = v_me,
      updated_at = now(), updated_by = v_me
    WHERE r.tenant_id = v_tenant AND r.id = v_run.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_me, v_role, 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', v_date, 'source', 'payroll_run', 'sourceId', v_run.id, 'number', v_number, 'lines', v_no, 'total', (greatest(v_salaries, 0) + v_employer + v_sum.commission)::text)),
           (v_tenant, v_me, v_role, 'payroll_run.approve', 'payroll_run', v_run.id,
      jsonb_build_object('number', v_number, 'month', v_run.month, 'date', v_date, 'net', v_sum.net::text, 'tax', v_sum.tax::text, 'commission', v_sum.commission::text));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.approve_payroll_run(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.approve_payroll_run(uuid) TO app_runtime;
--> statement-breakpoint
-- An approved run is paid out of a cash or bank account, on or after the day it went into the books.
CREATE FUNCTION app.pay_payroll_run(p_run uuid, p_account uuid, p_date date) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_run public.payroll_runs%ROWTYPE := app.hold_payroll_run(p_run);
  v_me uuid := app.current_user_id();
  v_journal uuid;
  v_number text;
BEGIN
  IF app.tenant_role() NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'a run is paid by the owner or an accountant' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_run.status <> 'approved' THEN
    RAISE EXCEPTION 'only an approved run is paid' USING ERRCODE = 'SE354';
  END IF;
  IF p_date IS NULL OR p_date > (now() AT TIME ZONE 'Asia/Karachi')::date OR p_date < v_run.journal_date THEN
    RAISE EXCEPTION 'a run is paid on or after the day it went into the books, and not before that day has come' USING ERRCODE = 'SE355';
  END IF;
  -- Held: nobody archives the account while the payment goes out of it.
  PERFORM 1 FROM public.accounts a
    WHERE a.tenant_id = v_run.tenant_id AND a.id = p_account AND a.control_type IN ('cash', 'bank') AND NOT a.is_group AND a.archived_at IS NULL
    FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'a run is paid from a cash or bank account that is in use' USING ERRCODE = 'SE359';
  END IF;
  PERFORM app.require_open_period(v_run.tenant_id, p_date);
  IF v_run.net > 0 THEN
    v_number := app.next_document_number('SP', p_date);
    SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
    INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, created_by)
      VALUES (v_run.tenant_id, p_date, 'payroll_payment', v_run.id, v_number, 'Salaries paid for ' || to_char(v_run.month, 'FMMonth YYYY') || ' (' || v_run.number || ')', v_me)
      RETURNING id INTO v_journal;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_run.tenant_id, v_journal, 1, app.control_account(v_run.tenant_id, 'payroll_payable'), v_run.net, 0, 'Salaries paid'),
             (v_run.tenant_id, v_journal, 2, p_account, 0, v_run.net, 'Salaries ' || v_run.number);
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (v_run.tenant_id, v_me, app.tenant_role(), 'journal.post', 'journal', v_journal,
        jsonb_build_object('date', p_date, 'source', 'payroll_payment', 'sourceId', v_run.id, 'number', v_number, 'lines', 2, 'total', v_run.net::text));
  END IF;
  UPDATE public.payroll_runs r SET status = 'paid', paid_on = p_date, pay_account_id = p_account, payment_journal_id = v_journal, payment_number = v_number,
      paid_at = now(), paid_by = v_me, updated_at = now(), updated_by = v_me
    WHERE r.tenant_id = v_run.tenant_id AND r.id = v_run.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_run.tenant_id, v_me, app.tenant_role(), 'payroll_run.pay', 'payroll_run', v_run.id,
      jsonb_build_object('number', v_run.number, 'paymentNumber', v_number, 'date', p_date, 'account', p_account, 'net', v_run.net::text));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.pay_payroll_run(uuid, uuid, date) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.pay_payroll_run(uuid, uuid, date) TO app_runtime;
--> statement-breakpoint
-- A draft or reviewed run is cancelled, with the reason: it never went into the books.
CREATE FUNCTION app.cancel_payroll_run(p_run uuid, p_reason text) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_run public.payroll_runs%ROWTYPE := app.hold_payroll_run(p_run);
BEGIN
  IF app.tenant_role() NOT IN ('owner', 'payroll_administrator') THEN
    RAISE EXCEPTION 'a run is cancelled by the owner or the payroll administrator' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF v_run.status NOT IN ('draft', 'reviewed') THEN
    RAISE EXCEPTION 'an approved run is not cancelled' USING ERRCODE = 'SE354';
  END IF;
  IF p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 3 AND 300 THEN
    RAISE EXCEPTION 'say why the run is cancelled' USING ERRCODE = 'SE356';
  END IF;
  UPDATE public.payroll_runs r SET status = 'cancelled', cancelled_at = now(), cancelled_by = app.current_user_id(), cancel_reason = btrim(p_reason),
      updated_at = now(), updated_by = app.current_user_id()
    WHERE r.tenant_id = v_run.tenant_id AND r.id = v_run.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, before, after)
    VALUES (v_run.tenant_id, app.current_user_id(), app.tenant_role(), 'payroll_run.cancel', 'payroll_run', v_run.id,
      jsonb_build_object('status', v_run.status), jsonb_build_object('status', 'cancelled', 'month', v_run.month, 'reason', btrim(p_reason)));
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.cancel_payroll_run(uuid, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.cancel_payroll_run(uuid, text) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: the shared lists (drizzle/0019_journal_documents.sql) ─────────────────────────
-- The run's two journals stand with it. Neither is reversed in this step: an approved run is
-- never cancelled, so neither has a function for a reversal.
CREATE FUNCTION app.journal_backed_payroll_run(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.payroll_runs r
      WHERE r.tenant_id = p_journal.tenant_id AND r.id = p_journal.source_id AND r.journal_id = p_journal.id
        AND r.number = p_journal.document_number AND r.journal_date = p_journal.journal_date AND r.status IN ('approved', 'paid'))
  $$;
--> statement-breakpoint
CREATE FUNCTION app.journal_backed_payroll_payment(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.payroll_runs r
      WHERE r.tenant_id = p_journal.tenant_id AND r.id = p_journal.source_id AND r.payment_journal_id = p_journal.id
        AND r.payment_number = p_journal.document_number AND r.paid_on = p_journal.journal_date AND r.status = 'paid')
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.journal_backed_payroll_run(public.journals), app.journal_backed_payroll_payment(public.journals) FROM PUBLIC;
--> statement-breakpoint
-- Payroll runs take a number when approved: PR-2627-00001.
CREATE FUNCTION app.document_type_pr() RETURNS text
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$ SELECT 'payroll run'::text $$;
