-- The audit rows only the functions above write.
CREATE FUNCTION app.audit_reserved_payroll_run(p_action text) RETURNS boolean
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$ SELECT p_action IN ('payroll_run.review', 'payroll_run.approve', 'payroll_run.pay', 'payroll_run.cancel') $$;
