-- The account the employer's EOBI and social security are expensed to: in the starting chart of
-- every new company, and given here to the companies that already have a chart (those with the
-- standard heading 5200 and no account numbered 5215).
CREATE FUNCTION app.chart_extra_payroll_statutory_expense()
  RETURNS TABLE (code text, name text, type text, parent text, is_group boolean, is_control boolean, control_type text)
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$ SELECT '5215', 'Employer EOBI and social security', 'expense', '5200', false, true, 'payroll_statutory_expense' $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.chart_extra_payroll_statutory_expense() FROM PUBLIC;
--> statement-breakpoint
INSERT INTO public.accounts (tenant_id, parent_id, code, name, type, is_group, is_control, control_type, created_by)
  SELECT p.tenant_id, p.id, '5215', 'Employer EOBI and social security', 'expense', false, true, 'payroll_statutory_expense', p.created_by
  FROM public.accounts p
  WHERE p.code = '5200' AND p.is_group AND p.type = 'expense'
    AND NOT EXISTS (SELECT 1 FROM public.accounts a WHERE a.tenant_id = p.tenant_id AND (a.code = '5215' OR a.control_type = 'payroll_statutory_expense'));
